export function computeScore(
	results: readonly Pick<ConceptResult, "weight" | "coverage">[]
): number {
	let earned = 0;
	let possible = 0;
	for (const { weight, coverage } of results) {
		earned += weight * COVERAGE_CREDIT[coverage];
		possible += weight;
	}
	if (possible === 0) {
		return 0;
	}
	return Math.round((earned / possible) * MAX_SCORE);
}

