const USER_API_KEY_PATTERN = /^sk-ant-[A-Za-z0-9_-]{20,300}$/;

type UserApiKey = { ok: true; key: string | undefined } | { ok: false };

/** Reads the optional bring-your-own-key header. The key is never logged or stored. */
function readUserApiKey(header: string | undefined): UserApiKey {
	if (!header) {
		return { ok: true, key: undefined };
	}
	return USER_API_KEY_PATTERN.test(header)
		? { ok: true, key: header }
		: { ok: false };
}

/**
 * The grader to use for a request. With `userApiKey` (bring your own key) a
 * one-off grader bills that key; it is never cached, stored, or logged.
 * Otherwise the shared grader bills the app's own key.
 */
export function getGrader(userApiKey?: string): Grader {
	if (userApiKey) {
		return createGrader({
			apiKey: userApiKey,
			model: env.GRADING_MODEL,
			effort: env.GRADING_EFFORT,
		});
	}
	if (!sharedGrader) {
		sharedGrader = createGrader({
			model: env.GRADING_MODEL,
			effort: env.GRADING_EFFORT,
		});
	}
	return sharedGrader;
}

