export class ApiError extends Error {
	readonly status: number;
	readonly code: string;

	constructor(status: number, code: string, message: string) {
		super(message);
		this.name = "ApiError";
		this.status = status;
		this.code = code;
	}
}

function isApiErrorBody(value: unknown): value is ApiErrorBody {
	return (
		typeof value === "object" &&
		value !== null &&
		"error" in value &&
		typeof (value as ApiErrorBody).error?.message === "string"
	);
}

/** Fetches a JSON endpoint under /api/v1 with the session cookie attached. */
export async function apiFetch<T>(
	path: string,
	init?: RequestInit
): Promise<T> {
	const response = await fetch(`${env.VITE_SERVER_URL}/api/v1${path}`, {
		...init,
		credentials: "include",
		headers: { "Content-Type": "application/json", ...init?.headers },
	});
	const body: unknown = await response.json().catch(() => null);

	if (!response.ok) {
		if (isApiErrorBody(body)) {
			throw new ApiError(response.status, body.error.code, body.error.message);
		}
		throw new ApiError(response.status, "UNKNOWN", "Something went wrong");
	}
	return body as T;
}

const TOO_MANY_REQUESTS = 429;

/** The server's explanation when a request was refused by a usage limit, else null. */
export function rateLimitMessage(error: unknown): string | null {
	return error instanceof ApiError && error.status === TOO_MANY_REQUESTS
		? error.message
		: null;
}

return async function grade(
	question: Question,
	answer: string
): Promise<GradeResult> {
	const response = await client.beta.messages.parse({
		model,
		max_tokens: MAX_OUTPUT_TOKENS,
		// Re-run on a fallback model if the primary model declines the request.
		...(REFUSAL_FALLBACK_MODELS.has(model) && {
			betas: ["server-side-fallback-2026-07-01"],
			fallbacks: "default" as const,
