			format: betaZodOutputFormat(graderOutputSchema),
		},
		system: GRADER_SYSTEM_PROMPT,
		messages: [
			{ role: "user", content: buildGradingRequest(question, answer) },
		],
	});

	if (response.stop_reason === "refusal") {
		throw new GradingError("The grader declined to grade this answer");
	}
	if (response.stop_reason === "max_tokens") {
		throw new GradingError("The grader ran out of output tokens");
	}
	if (!response.parsed_output) {
		throw new GradingError(
			"The grader returned output that did not match the schema"
		);
