		])
	);

	const results: ConceptResult[] = concepts.map((concept) => {
		const assessment = assessments.get(concept.id);
		return {
			conceptId: concept.id,
			name: concept.name,
			weight: concept.weight,
			coverage: assessment?.coverage ?? "missing",
			evidence: assessment?.evidence ?? "",
			explanation: assessment?.explanation ?? concept.expectation,
		};
	});

	return {
		score: computeScore(results),
		summary: output.summary,
		concepts: results,
		strengths: output.strengths,
		misconceptions: output.misconceptions,
	};
}

export function classifyGradingError(error: unknown): GradingFailureCode {
	if (
		error instanceof Anthropic.AuthenticationError ||
		error instanceof Anthropic.PermissionDeniedError
	) {
		return "KEY_REJECTED";
	}
	if (error instanceof Anthropic.RateLimitError) {
		return "RATE_LIMITED";
	}
	if (
		error instanceof Anthropic.BadRequestError &&
		CREDIT_BALANCE_PATTERN.test(error.message)
	) {
		return "NO_CREDIT";
	}
	return "GRADER_ERROR";
}

