function getRecognitionConstructor(): RecognitionConstructor | null {
	if (typeof window === "undefined") {
		return null;
	}
	const speechWindow = window as typeof window & {
		SpeechRecognition?: RecognitionConstructor;
		webkitSpeechRecognition?: RecognitionConstructor;
	};
	return (
		speechWindow.SpeechRecognition ??
		speechWindow.webkitSpeechRecognition ??
		null
	);
}

const start = useCallback(() => {
	const RecognitionCtor = getRecognitionConstructor();
	if (!RecognitionCtor || recognitionRef.current) {
		return;
	}

	const recognition = new RecognitionCtor();
	recognition.continuous = true;
	recognition.interimResults = true;
	recognition.lang = lang;

	recognition.onresult = (event) => {
		let interimText = "";
		const newResults = Array.from(event.results).slice(event.resultIndex);
		for (const result of newResults) {
			const transcript = result[0]?.transcript ?? "";
			if (result.isFinal) {
				onTranscriptRef.current(transcript);
			} else {
				interimText += transcript;
			}
		}
		setInterim(interimText);
	};

recognition.onerror = (event) => {
	if (BENIGN_ERRORS.has(event.error)) {
		return;
	}
	wantedRef.current = false;
	if (event.error === SERVICE_UNREACHABLE) {
		setServiceUnreachable(true);
		return;
	}
	setError(ERROR_MESSAGES[event.error] ?? DEFAULT_ERROR_MESSAGE);
};

recognition.onend = () => {
	if (wantedRef.current) {
		try {
			recognition.start();
			return;
		} catch {
			wantedRef.current = false;
		}
	}
	recognitionRef.current = null;
	setListening(false);
	setInterim("");
};

