type UserApiKey = { ok: true; key: string | undefined } | { ok: false };

/** Reads the optional bring-your-own-key header. The key is never logged or stored. */
function readUserApiKey(header: string | undefined): UserApiKey {
	if (!header) {
		return { ok: true, key: undefined };
	}
	return USER_API_KEY_PATTERN.test(header)
		? { ok: true, key: header }
		: { ok: false };
}

function useNeighbours(questionId: string): Neighbours {
	const { data: questions = [] } = useQuery(questionsQuery);
	const index = questions.findIndex((entry) => entry.id === questionId);
	if (index < 0) {
		return { position: "", previousId: undefined, nextId: undefined };
	}
	return {
		position: `question ${index + 1} of ${questions.length}`,
		previousId: questions[index - 1]?.id,
		nextId: questions[index + 1]?.id,
	};
}

